.darma-loader-darma-b17-tractor-plow { --accent: var(--loader-color, #15803d); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 130px); height: calc(var(--loader-size, 130px) * .62); position: relative; overflow: hidden; }
.darma-loader-darma-b17-tractor-plow .darma-loader-darma-b17-tractor-plow__soil { position: absolute; left: 0; right: 0; bottom: 8%; height: 6%; border-radius: 3px; background: color-mix(in srgb, #78350f 70%, transparent); }
.darma-loader-darma-b17-tractor-plow .darma-loader-darma-b17-tractor-plow__rig { position: absolute; left: 22%; bottom: 12%; width: 54%; height: 60%; animation: darma-loader-darma-b17-tractor-plow-plow-bump calc(var(--loader-speed, 1s) * .7) ease-in-out infinite; }
.darma-loader-darma-b17-tractor-plow .darma-loader-darma-b17-tractor-plow__cab { position: absolute; left: 44%; bottom: 34%; width: 34%; height: 50%; border-radius: 5px 6px 2px 2px; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); }
.darma-loader-darma-b17-tractor-plow .darma-loader-darma-b17-tractor-plow__hood { position: absolute; left: 4%; bottom: 34%; width: 44%; height: 30%; border-radius: 4px; background: var(--accent); }
.darma-loader-darma-b17-tractor-plow .darma-loader-darma-b17-tractor-plow__rear { position: absolute; right: 2%; bottom: 0; width: 40%; height: 52%; border-radius: 50%; background: radial-gradient(circle, var(--accent-2) 0 26%, #1e293b 28%); animation: darma-loader-darma-b17-tractor-plow-plow-roll calc(var(--loader-speed, 1s) * .7) linear infinite; }
.darma-loader-darma-b17-tractor-plow .darma-loader-darma-b17-tractor-plow__front { position: absolute; left: 2%; bottom: 4%; width: 26%; height: 34%; border-radius: 50%; background: radial-gradient(circle, var(--accent-2) 0 26%, #1e293b 28%); animation: darma-loader-darma-b17-tractor-plow-plow-roll calc(var(--loader-speed, 1s) * .45) linear infinite; }
.darma-loader-darma-b17-tractor-plow i { position: absolute; bottom: 2%; width: 7%; height: 5%; border-radius: 2px 2px 0 0; background: color-mix(in srgb, #78350f 85%, transparent); animation: darma-loader-darma-b17-tractor-plow-plow-furrow calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b17-tractor-plow i:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b17-tractor-plow i:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
@keyframes darma-loader-darma-b17-tractor-plow-plow-roll { to { transform: rotate(1turn); } }
@keyframes darma-loader-darma-b17-tractor-plow-plow-bump { 0%, 100% { transform: translateY(0) rotate(0deg); } 40% { transform: translateY(-2%) rotate(-1deg); } 75% { transform: translateY(-1%) rotate(1deg); } }
@keyframes darma-loader-darma-b17-tractor-plow-plow-furrow { 0% { left: 24%; opacity: 0; } 12% { opacity: 1; } 88% { opacity: 1; } 100% { left: -8%; opacity: 0; } }

